import 'package:flutter/material.dart';
const apiUrl=String.fromEnvironment('AFHOMES_API_URL',defaultValue:'http://10.0.2.2:3001');
void main()=>runApp(const App()); class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'AFhomes',theme:ThemeData(colorSchemeSeed:const Color(0xff176b87),useMaterial3:true),home:const Home());}
class Home extends StatelessWidget{const Home({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('AFhomes VIP')),body:ListView(padding:const EdgeInsets.all(20),children:[const Card(child:Padding(padding:EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Welcome',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),Text('Activate your VIP card and manage your membership.'),SizedBox(height:16),Text('Points · Benefits · Transactions · Support')]))),for(final x in ['Activate VIP','Digital VIP Card','Points','Membership','Benefits','Transactions','Notifications','Customer Support','Security','Registered Devices'])ListTile(title:Text(x),trailing:const Icon(Icons.chevron_right))]),bottomNavigationBar:Padding(padding:const EdgeInsets.all(8),child:Text('API: $apiUrl',textAlign:TextAlign.center))));}
